 /// that cannot receive a monomorphic `assume_specification` in Verus.
 #[verus_verify(external_body)]
 #[verus_spec(ret =>
     ensures ret as int == pa@,
 )]
 pub fn pa_into_raw(pa: PageAligned<PhysicalAddress>) -> usize {
     pa.into_raw_value()
 }

