140.     ///
141.     /// # Return Values
142.     ///
143.     /// Upon success, the address of the allocated frame is returned. Upon failure, an error is
144.     /// returned instead.
145.     ///
146.     #[verus_spec(result =>
147.         requires
148.             old(self).inv(),
149.         ensures
150.             self.inv(),
151.             match result {
152.                 Ok(frame) => {
153.                     let page_index = (frame@ - old(self)@.start) / spec_page_size();
154.                     &&& frame.inv()
155.                     &&& 0 <= page_index < old(self)@.num_pages
156.                     &&& !old(self)@.used_page_indices.contains(page_index)
157.                     &&& self@ == KpoolView {
158.                         used_page_indices: old(self)@.used_page_indices.insert(page_index),
159.                         ..old(self)@
160.                     }
161.                 },
162.                 Err(_) => {
163.                     &&& forall|i: int| 0 <= i < old(self)@.num_pages ==> old(self)@.used_page_indices.contains(i)
164.                     &&& self@ == old(self)@
165.                 },
166.             },
167.     )]
168.     fn alloc(&mut self) -> Result<FrameAddress, Error> {
169.         proof! {
170.             self.lemma_internal_inv();
171.         }
172.         let index: usize = match self.bitmap.alloc() {
173.             Ok(index) => index,
174.             Err(error) => {
175.                 #[cfg(not(verus_keep_ghost))]
176.                 error!("{error:?}");
177.                 proof! {
178.                     // bitmap.alloc() Err => bitmap is full => all pages are used
179.                     assert(old(self).bitmap@.is_full());
180.                     // is_full means all bits 0..num_bits are set
181.                     assert(forall|i: int| 0 <= i < old(self)@.num_pages ==> old(self)@.used_page_indices.contains(i));
182.                 }
183.                 return Err(error);
184.             },
185.         };
186.         proof! {
187.             // index from bitmap.alloc: 0 <= index < num_bits
188.             assert(0 <= index < self.bitmap@.num_bits);
189.             assert(spec_page_size() > 0);
190.             // Re-establish internal_inv (bitmap mutated but properties preserved)
191.             self.lemma_internal_inv_intro();
192. 
193.             // Prove index * PAGE_SIZE doesn't overflow using multiplication lemma
194.             vstd::arithmetic::mul::lemma_mul_strict_inequality(
195.                 index as int,
196.                 self.bitmap@.num_bits,
197.                 spec_page_size(),
198.             );
199.             // Now we know: index * spec_page_size() < num_bits * spec_page_size()
200.             assert(self.base@ + self.bitmap@.num_bits * spec_page_size() <= usize::MAX as int + 1);
201.             assert(self.base@ >= 0);
202.             // So index * page_size < num_bits * page_size <= usize::MAX + 1 - base@ <= usize::MAX + 1
203.             assert((index as int) * spec_page_size() <= usize::MAX as int);
204. 
205.             // Prove base@ + index * PAGE_SIZE doesn't overflow
206.             assert(self.base@ + (index as int) * spec_page_size() <= usize::MAX as int);
207. 
208.             // Prove page-alignment for FrameAddress::from_raw_value precondition
209.             assert(self.base@ % spec_page_size() == 0);
210.         }
211.         // VERUS REWRITE: pa_into_raw wrapper needed; FrameAddress::from_raw_value equivalent to FrameAddress::new(PageAligned::from_address(PhysicalAddress::from_raw_value(addr)?)?)
212.         let addr: usize = pa_into_raw(self.base) + index * mem::PAGE_SIZE;        proof! {
213.             assert(addr as int == self.base@ + (index as int) * spec_page_size());
214.             // Prove page alignment: (base@ + index * page_size) % page_size == 0
215.             vstd::arithmetic::div_mod::lemma_mod_multiples_vanish(
216.                 index as int,
217.                 self.base@,
218.                 spec_page_size(),
219.             );
220.             assert(addr as int % spec_page_size() == 0);

