137. #[verus_verify]
138. struct Inner {
139.     /// A sparse bitmap that keeps track of free/used frames.
140.     bitmap: SparseBitmap,
141. }
142. 
143. #[verus_verify]
144. impl Inner {
145.     ///
146.     /// # Description
147.     ///
148.     /// Allocates a frame.
149.     ///
150.     /// # Returns
151.     ///
152.     /// Upon success, the address of the allocated frame is returned. Upon failure, an error is
153.     /// returned instead.
154.     ///
155.     #[verus_spec(result =>
156.         requires
157.             old(self).inv(),
158.         ensures
159.             self.inv(),
160.             match result {
161.                 Ok(frame) => {
162.                     &&& frame.inv()
163.                     &&& old(self)@.free_frames.contains(frame@)
164.                     &&& self@ == old(self)@.spec_alloc(frame@)
165.                 },
166.                 Err(_) => {
167.                     &&& self@ == old(self)@
168.                     &&& old(self)@.free_frames.is_empty()
169.                 }
170.             },
171.     )]
172.     fn alloc(&mut self) -> Result<FrameAddress, Error> {
173.         proof! { admit(); }
174.         let index: usize = match self.bitmap.alloc() {
175.             Ok(index) => index,
176.             Err(error) => {
177.                 #[cfg(not(verus_keep_ghost))]
178.                 error!("{error:?}");
179.                 return Err(error);
180.             },
181.         };
182.         // VERUS REWRITE: merged FrameNumber::from_raw_value + FrameAddress::from_frame_number
183.         // into bitmap_index_to_frame_addr wrapper (isolates conversion trust boundary).
184.         bitmap_index_to_frame_addr(index)
185.     }
186. 
187.     ///
188.     /// # Description
189.     ///
190.     /// Frees a frame that was previously allocated.
191.     ///
192.     /// # Parameters
193.     ///
194.     /// - `frame`: Address of the frame to free.
195.     ///
196.     /// # Returns
197.     ///
198.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
199.     ///
200.     #[verus_spec(result =>
201.         requires
202.             old(self).inv(),
203.             frame.inv(),
204.         ensures
205.             self.inv(),
206.             match result {
207.                 Ok(()) => {
208.                     &&& old(self)@.allocated_frames.contains(frame@)
209.                     &&& self@ == old(self)@.spec_free(frame@)
210.                 },
211.                 Err(_) => {
212.                     &&& self@ == old(self)@
213.                     &&& !old(self)@.allocated_frames.contains(frame@)
214.                 }
215.             },
216.     )]
217.     fn free(&mut self, frame: FrameAddress) -> Result<(), Error> {
218.         proof! { admit(); }
219.         // VERUS REWRITE: frame.into_frame_number().into_raw_value() → wrapper
220.         let frame_number: usize = frame_addr_to_bitmap_index(frame);
221.         match self.bitmap.clear(frame_number) {
222.             Ok(()) => Ok(()),
223.             Err(error) => {
224.                 #[cfg(not(verus_keep_ghost))]
225.                 error!("{error:?} (frame={frame:?})");
226.                 Err(error)
227.             },
228.         }
229.     }
