258.                 }
259.             },
260.     )]
261.     fn book(&mut self, phys_addr: PageAligned<PhysicalAddress>) -> Result<(), Error> {
262.         proof! { admit(); }
263.         // VERUS REWRITE: phys_addr.into_frame_number().into_raw_value() → wrapper
264.         let frame_number: usize = page_aligned_pa_to_bitmap_index(phys_addr);
265.         match self.bitmap.set(frame_number) {
266.             Ok(()) => Ok(()),
267.             Err(error) => {
268.                 #[cfg(not(verus_keep_ghost))]
269.                 error!("{error:?} (phys_addr={phys_addr:?})");
270.                 Err(error)
271.             },
272.         }
273.     }
