275.     ///
276.     /// # Description
277.     ///
278.     /// Allocates all frames in the given region.
279.     ///
280.     /// # Parameters
281.     ///
282.     /// - `region`: Physical memory region whose frames should be booked.
283.     ///
284.     /// # Returns
285.     ///
286.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
287.     ///
288.     #[verus_spec(result =>
289.         requires
290.             old(self).inv(),
291.             region.inv(),
292.         ensures
293.             self.inv(),
294.             ({
295.                 let start_frame_number = region@.start / spec_page_size();
296.                 let end_frame_number = (region@.start + region@.size) / spec_page_size();
297.                 let frame_numbers = vstd::set_lib::set_int_range(start_frame_number, end_frame_number);
298.                 let frames = frame_numbers.map(|i: int| i * spec_page_size());
299.                 match result {
300.                     Ok(()) => {
301.                         &&& frames.subset_of(old(self)@.free_frames)
302.                         &&& self@ == old(self)@.spec_alloc_range(frames)
303.                     },
304.                     Err(_) => {
305.                         &&& self@ == old(self)@
306.                         &&& !frames.subset_of(old(self)@.free_frames)
307.                     },
308.                 }
309.             }),
310.     )]
311.     fn alloc_range(
312.         &mut self,
313.         region: &TruncatedMemoryRegion<PhysicalAddress>,
314.     ) -> Result<(), Error> {
315.         proof! { admit(); }
316.         // VERUS REWRITE: region.start().into_frame_number().into_raw_value() → wrapper
317.         let start_frame_number: usize = region_start_frame_number(region);
318.         // VERUS REWRITE: replaced `start + size/FRAME_SIZE - 1` and `..=` (inclusive range)
319.         // with exclusive upper bound. RangeInclusive<usize> lacks ForLoopGhostIteratorNew.
320.         // VERUS REWRITE: region.size() → wrapper
321.         let num_frames: usize = region_size_raw(region) / mem::FRAME_SIZE;
322.         let end_frame_number: usize = start_frame_number + num_frames;
323. 
324.         // When nightly-performance-optimizations is off, verify that every frame index in the
325.         // range is covered by the sparse bitmap. SparseBitmap::test() returns Ok(false) for
326.         // uncovered indices, which would incorrectly appear as "free" and pass the check below,
327.         // only to fail on set(). With the feature enabled this check is elided because
328.         // PhysicalAddress construction already guarantees valid physical addresses.
329.         #[cfg(not(feature = "nightly-performance-optimizations"))]
330.         #[verus_spec(invariant(true))]
331.         for index in start_frame_number..end_frame_number {
332.             proof! { admit(); }
333.             if self.bitmap.find_chunk(index).is_none() {
334.                 let uncovered_addr: usize = index * mem::FRAME_SIZE;
335.                 let reason: &str = "frame index not covered by any bitmap chunk";
336.                 #[cfg(not(verus_keep_ghost))]
337.                 error!("{} (frame={:#010x}, region={:?})", reason, uncovered_addr, region);
338.                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
339.             }
340.         }
341. 
342.         // Check if all frames in the range are free.
343.         #[verus_spec(invariant(true))]
344.         for index in start_frame_number..end_frame_number {
345.             proof! { admit(); }
346.             match self.bitmap.test(index) {
347.                 Ok(false) => {
348.                     // Frame is free — nothing to do.
349.                 },
350.                 Ok(true) => {
351.                     let conflicting_addr: usize = index * mem::FRAME_SIZE;
352.                     // VERUS REWRITE: region.start().into_raw_value() → wrapper
353.                     let region_start: usize = region_start_raw(region);
354.                     let region_end: usize = region_start.saturating_add(region_size_raw(region));
355.                     let reason: &str = "frame is already allocated";
356.                     #[cfg(not(verus_keep_ghost))]
357.                     error!(
358.                         "{} (frame={:#010x}, region_start={:#010x}, region_end={:#010x})",
359.                         reason, conflicting_addr, region_start, region_end
360.                     );
361.                     return Err(Error::new(ErrorCode::OutOfMemory, reason));
362.                 },
363.                 Err(err) => return Err(err),
364.             }
365.         }
366. 
367.         // Book all frames in the range.
368.         #[verus_spec(invariant(true))]
369.         for index in start_frame_number..end_frame_number {
370.             proof! { admit(); }
371.             if let Err(error) = self.bitmap.set(index) {
372.                 #[cfg(not(verus_keep_ghost))]
373.                 error!("{error:?} (region={region:?})");
374.                 return Err(error);
375.             }
376.         }
377. 
378.         Ok(())
379.     }
380. }
