     /// Whether a global index is covered by some chunk.
     pub open spec fn is_covered(&self, index: int) -> bool {
         exists|i: int|
             #![trigger self.chunks[i]]
             0 <= i < self.chunks.len()
             && self.chunks[i].0 <= index
             && index < self.chunks[i].0 + self.chunks[i].1
     }

