 ///
 /// # Description
 ///
 /// A type that represents the type of a memory region.
 ///
 #[derive(Debug, Clone, Copy, Eq, PartialEq)]
 #[verus_verify]
 pub enum MemoryRegionType {
     /// Usable memory.
     Usable,
     /// Reserved memory.
     Reserved,
     /// Memory mapped I/O.
     Mmio,
     /// Bad memory.
     Bad,
 }

